1021				if endIdx < r.anchorIdx || endIdx > r.endIdx {
1022					continue // 范围不含该末帧的校正不改变它对应的值
1023				}
1024				if !r.fullyBased {
1025					checkable = false
1026					break
1027				}
1028				if first {
1029					want = cr.Poses[endIdx-r.anchorIdx].Before
1030					first = false
1031				}
1032			}
1033			if !checkable {
1034				continue
1035			}
